import { CandlestickChartAdapter, useCandlestickChart } from '@dreadnought/react/unstyled';
const data = [{id:'a',label:'Пн',open:100,high:120,low:90,close:110}];
function Summary() { const {candles,page} = useCandlestickChart(); return <p>{candles.length} периодов; страница {page.page}</p>; }
export function Example() { return <CandlestickChartAdapter data={data} label="Котировки"><Summary /><CandlestickChartAdapter.Plot height={180} tooltipContent={({defaultContent}) => <div>OHLC{defaultContent}</div>}>{({defaultContent}) => defaultContent}</CandlestickChartAdapter.Plot><CandlestickChartAdapter.Table /><CandlestickChartAdapter.Pagination /></CandlestickChartAdapter>; }

import { CandlestickChartAdapter } from '@dreadnought/react/unstyled';
const data = [{ id: 'a', label: 'Пн', open: 100, high: 114, low: 96, close: 110 }, { id: 'b', label: 'Вт', open: 110, high: 117, low: 99, close: 103 }];
export function Example() { return <CandlestickChartAdapter label="Котировки" data={data} formatValue={value => value.toFixed(2)} />; }
